<?php
require_once __DIR__.'/auth.php'; require_once __DIR__.'/layout.php'; require_once __DIR__.'/../includes/lcc_payroll.php';
$employee=current_employee($conn);if(!$employee){header('Location: logout.php');exit;}
$id=(int)$employee['employee_id'];
$stmt=$conn->prepare('SELECT l.loan_id,l.loan_date,l.principal,l.installment,l.repayment_start,l.status,t.name AS type_name,COALESCE(SUM(r.amount),0) AS repaid FROM employee_loans l JOIN loan_types t ON t.loan_type_id=l.loan_type_id LEFT JOIN loan_repayments r ON r.loan_id=l.loan_id WHERE l.employee_id=? GROUP BY l.loan_id ORDER BY l.loan_id DESC');
$stmt->bind_param('i',$id);$stmt->execute();$loans=$stmt->get_result();
$loanId=(int)($_GET['id']??0);$repayments=null;
if($loanId>0){$stmt=$conn->prepare('SELECT r.amount,r.posted_at,p.period_start,p.period_end FROM loan_repayments r JOIN employee_loans l ON l.loan_id=r.loan_id JOIN payroll_records p ON p.payroll_id=r.payroll_id WHERE r.loan_id=? AND l.employee_id=? ORDER BY r.repayment_id');$stmt->bind_param('ii',$loanId,$id);$stmt->execute();$repayments=$stmt->get_result();}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="icon" href="../assets/favicon.png"><title>LCC Payroll System</title><link rel="stylesheet" href="../assets/css/app.css"><link rel="stylesheet" href="../assets/css/employee.css"><link rel="stylesheet" href="../assets/css/apple-system.css"><script src="../assets/js/app.js" defer></script></head><body><div class="app"><?php employee_sidebar('loans'); ?><main class="main"><?php employee_topbar('My Loans'); ?><div class="content"><div class="page-heading"><div><div class="eyebrow">EMPLOYEE PORTAL</div><h1>My Loans</h1><p>Only your loans and posted repayments are shown.</p></div></div><section class="card"><div class="card-head"><div><h2>Loan Balances</h2></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Type</th><th>Loan Date</th><th>Principal</th><th>Repaid</th><th>Balance</th><th>Installment</th><th>Start</th><th>Status</th><th></th></tr></thead><tbody><?php if(!$loans->num_rows): ?><tr><td colspan="9" class="empty">No loans on your account.</td></tr><?php else: while($row=$loans->fetch_assoc()): ?><tr><td><?php echo e($row['type_name']); ?></td><td><?php echo e($row['loan_date']); ?></td><td><?php echo money($row['principal']); ?></td><td><?php echo money($row['repaid']); ?></td><td><strong><?php echo money(number_format((lcc_cents($row['principal'])-lcc_cents($row['repaid']))/100,2,'.','')); ?></strong></td><td><?php echo money($row['installment']); ?></td><td><?php echo e($row['repayment_start']); ?></td><td><span class="badge"><?php echo e($row['status']); ?></span></td><td><a class="btn btn-secondary btn-small" href="loans.php?id=<?php echo (int)$row['loan_id']; ?>">History</a></td></tr><?php endwhile; endif; ?></tbody></table></div></section><?php if($repayments): ?><section class="card"><div class="card-head"><div><h2>Posted Repayments · Loan #<?php echo $loanId; ?></h2></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Period</th><th>Amount</th><th>Posted</th></tr></thead><tbody><?php if(!$repayments->num_rows): ?><tr><td colspan="3" class="empty">No repayments posted.</td></tr><?php else: while($row=$repayments->fetch_assoc()): ?><tr><td><?php echo e($row['period_start'].' – '.$row['period_end']); ?></td><td><?php echo money($row['amount']); ?></td><td><?php echo e($row['posted_at']); ?></td></tr><?php endwhile; endif; ?></tbody></table></div></section><?php endif; ?></div></main></div></body></html>
